// Controller actual S -> N/P public lifecycle; driver operates this PID only.
#![forbid(unsafe_code)]
use serde_json::{Value,json};
use water_contracts::v1::OpaqueId;
use water_scope_registry::v1::{Registry,RegistryError};
use water_native_picker::v1 as s;
fn main(){let index:Value=serde_json::from_str(&std::fs::read_to_string(std::env::var("WATER_PICKER_INDEX").unwrap()).unwrap()).unwrap();let root=index["root"].as_str().unwrap();let id=OpaqueId::new("picker-public").unwrap();let options=s::PickerOptions::new(root).unwrap();let mut registry=Registry::new(2).unwrap();eprintln!("WATER_PICKER_CASE cancel");assert!(s::select_scope(&mut registry,&id,&options).unwrap().is_none());assert!(registry.is_empty());eprintln!("WATER_PICKER_CASE select");let selected=s::select_scope(&mut registry,&id,&options).unwrap().unwrap();assert_eq!(selected.scope().scope_id(),&id);assert_eq!(selected.root_path().to_lowercase(),root.to_lowercase());let permit=registry.begin_scan(selected.scope()).unwrap();let observed=registry.check_permit(&permit).unwrap();assert_eq!(observed.identity(),water_native_root::v1::open_directory(&id,root).unwrap().observation().identity());registry.finish(&permit).unwrap();eprintln!("WATER_PICKER_CASE select");let duplicate=s::select_scope(&mut registry,&OpaqueId::new("duplicate-root").unwrap(),&options);assert!(matches!(duplicate,Err(s::PickerError::Source(RegistryError::DuplicateRoot))));assert_eq!(registry.len(),1);registry.revoke(selected.scope()).unwrap();assert!(registry.begin_scan(selected.scope()).is_err());assert!(registry.is_empty());println!("{}",json!({"actual_S_N_P":true,"cancel_no_registration":true,"actual_result_path":true,"duplicate_root_and_revoke":true,"R_scan_tested":false}));}
